{
  "name": "@cat4869/token-lean",
  "version": "0.2.0",
  "type": "module",
  "main": "./src/index.ts",
  "scripts": {
    "check": "node scripts/run-bun.mjs --check src/index.ts src/distillation.ts test/index.test.ts test/fixtures.test.ts test/current-e2e-replay.ts test/historical-replay.ts",
    "test": "node scripts/run-bun.mjs test",
    "pack:dry-run": "node scripts/run-bun.mjs pm pack --dry-run",
    "publish:dry-run": "npm publish --dry-run --access=public",
    "prepublishOnly": "bun run check && bun run test && bun run pack:dry-run",
    "replay:historical": "OPENCODE_DB_PATH=${OPENCODE_DB_PATH:-$HOME/.local/share/opencode/opencode.db} node scripts/run-bun.mjs test/historical-replay.ts"
  },
  "description": "OpenCode plugin that reduces repeated OMO task output, safely distills reconstructable background results, and compresses built-in tool descriptions.",
  "publishConfig": {
    "access": "public"
  },
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src/*.ts",
    "scripts/*.mjs",
    "config.json",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "oh-my-openagent",
    "omo",
    "token-optimization",
    "context-compression"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cat4869/token-lean.git"
  },
  "homepage": "https://github.com/cat4869/token-lean#readme",
  "bugs": {
    "url": "https://github.com/cat4869/token-lean/issues"
  },
  "author": "cat4869",
  "license": "MIT",
  "engines": {
    "bun": ">=1.2.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.15"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.15"
  }
}
